#!/usr/bin/env node
/**
 * Regenerate app/lib/language/parent-locales.generated.ts from Unicode CLDR's `parentLocales` (a small table: which
 * locale a regional one inherits from, e.g. es-MX -> es-419, pt-AO -> pt-PT, en-AU -> en-001; "und" means "do not fall
 * back by truncation", the script variants such as sr-Latn).
 *
 *   node scripts/cldr-parent-locales.mjs
 *
 * Needs network, so it is NOT part of verify: run it when upgrading CLDR, and commit the result. The generated file
 * records the source URL and CLDR version it came from.
 */
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const SOURCE = "https://raw.githubusercontent.com/unicode-org/cldr-json/main/cldr-json/cldr-core/supplemental/parentLocales.json";
const OUT = join(dirname(fileURLToPath(import.meta.url)), "../app/lib/language/parent-locales.generated.ts");

const response = await fetch(SOURCE);
if (!response.ok) throw new Error(`${SOURCE}: HTTP ${response.status}`);
const json = await response.json();
const table = json.supplemental.parentLocales.parentLocale;
const version = json.supplemental.version._cldrVersion;
const rows = Object.entries(table).sort(([a], [b]) => a.localeCompare(b)).map(([child, parent]) => `  ${JSON.stringify(child)}: ${JSON.stringify(parent)},`);
writeFileSync(OUT, [
  "// GENERATED by scripts/cldr-parent-locales.mjs. Do not edit.",
  `// Source: ${SOURCE}`,
  `// CLDR version: ${version}. "und" = the locale does not inherit by truncation.`,
  "export const PARENT_LOCALES: Readonly<Record<string, string>> = {",
  ...rows,
  "};",
  "",
].join("\n"));
console.log(`wrote ${rows.length} parent locales (CLDR ${version})`);
